def subarray_sum(nums, k):
    prefix_counts = {0: 1}
    prefix_sum = 0
    total = 0

    for num in nums:
        prefix_sum += num
        total += prefix_counts.get(prefix_sum - k, 0)
        prefix_counts[prefix_sum] = prefix_counts.get(prefix_sum, 0) + 1

    return total

